"""Isolated R105 development routes; no changes to the Seoul rule engine."""
import json, math, re, secrets, threading, time, zlib, base64, hashlib
from functools import lru_cache
from urllib.parse import urlsplit, quote
from pathlib import Path
import requests
from fastapi import APIRouter, HTTPException, Request, Depends
from fastapi.responses import Response
from pydantic import BaseModel, Field
from shapely.geometry import shape, box
from shapely.geometry.polygon import orient
from shapely.ops import unary_union, transform
from pyproj import Geod, Transformer
GEOD=Geod(ellps='WGS84')
FACILITY_NAMES=['도로','교통시설','공간시설','유통·공급시설','공공·문화체육시설','방재시설','보건위생시설','환경기초시설','기타 기반시설']
LAYERS={'LP_PA_CBND_BUBUN':'연속지적',**{f'LT_C_UQ11{i}':n for i,n in enumerate(['도시지역','관리지역','농림지역','자연환경보전지역'],1)},**{f'LT_C_UPISUQ15{i}':FACILITY_NAMES[i-1] for i in range(1,10)}}
# Seoul municipal GeoServer: 25 district boundaries, retrieved 2026-10-28.
# Routing reference only; not a substitute for a legal boundary determination.
SEOUL_REFERENCE_SOURCE='https://map.seoul.go.kr/geoserver/wfs?service=WFS&version=1.0.0&request=GetFeature&typeName=tile_map:v_tl_scco_sig_tms&outputFormat=application/json&srsName=EPSG:4326&maxFeatures=30'
SEOUL_REFERENCE_SHA256='f7296c1d718467299f09641d36ea0bad847732fbc2fe7bc7300c6df22b03e43c'
_SEOUL_REFERENCE_Z=''
@lru_cache(maxsize=1)
def seoul_reference():
    raw=zlib.decompress(base64.b64decode(_SEOUL_REFERENCE_Z))
    if hashlib.sha256(raw).hexdigest()!=SEOUL_REFERENCE_SHA256:raise ValueError('boundary reference verification failed')
    g=shape(json.loads(raw));project=Transformer.from_crs(4326,5179,always_xy=True).transform
    metric=transform(project,g)
    if not g.is_valid:raise ValueError('boundary reference invalid')
    return metric.buffer(-100),metric.buffer(100),project

def offline_region(g):
    try:
        inside,outside,project=seoul_reference();metric=transform(project,g)
        if inside.covers(metric):return 'SEOUL'
        if outside.disjoint(metric):return 'OUTSIDE_OR_MIXED'
    except Exception:pass
    return None

class ChannelFailure(RuntimeError):
    def __init__(self,code):self.code=code;super().__init__(code)

class VWorldChannel:
    """Independent, bounded transport. Display failures never pause input picking."""
    def __init__(self,slots,pause_on_transport_error=True):
        self.slots=threading.BoundedSemaphore(slots);self.lock=threading.Lock();self.until=0.0;self.code=None
        self.pause_on_transport_error=pause_on_transport_error
    def request(self,url,params,expected):
        # Only the two application-owned endpoints may use this helper.
        if url not in ('https://api.vworld.kr/req/data','https://api.vworld.kr/req/wms'):raise ChannelFailure('REQUEST_FAILED')
        with self.lock:
            if time.monotonic()<self.until:raise ChannelFailure('TEMPORARILY_PAUSED')
        if not self.slots.acquire(timeout=.5):raise ChannelFailure('TEMPORARILY_PAUSED')
        try:
            # Recheck after acquiring; concurrent tile requests must honor the pause.
            with self.lock:
                if time.monotonic()<self.until:raise ChannelFailure('TEMPORARILY_PAUSED')
            domain=str(params.get('domain') or '').rstrip('/')
            headers={'Referer':domain+'/','Accept':'image/png' if expected=='png' else 'application/json','User-Agent':'urban-strategy-development/105.3'}
            inner=requests.Request('GET',url,params=params).prepare().url
            routes=[(url,params,'direct'),('https://map.vworld.kr/proxy.do?url='+quote(inner,safe=''),None,'vworld_proxy')]
            for endpoint,query,route in routes:
                try:
                    r=requests.get(endpoint,params=query,headers=headers,timeout=(3,6),allow_redirects=False)
                except requests.RequestException:continue
                if r.status_code==429:
                    r.close();self.pause('RATE_LIMIT');raise ChannelFailure('RATE_LIMIT')
                if r.status_code in (401,403):
                    r.close();raise ChannelFailure('PROVIDER_REJECTED')
                if r.status_code!=200:
                    r.close();continue
                if expected=='png':valid=r.content.startswith(b'\x89PNG\r\n\x1a\n')
                else:
                    try:valid=isinstance(r.json(),dict)
                    except Exception:valid=False
                if valid:
                    with self.lock:self.until=0.0;self.code=None
                    return r,route
                r.close()
            if self.pause_on_transport_error:self.pause('PROVIDER_UNREACHABLE')
            raise ChannelFailure('PROVIDER_UNREACHABLE')
        finally:self.slots.release()
    def pause(self,code):
        with self.lock:self.until=time.monotonic()+15;self.code=code
    def snapshot(self):
        with self.lock:return {'paused':time.monotonic()<self.until,'retry_after_seconds':max(0,math.ceil(self.until-time.monotonic())),'last_error_code':self.code}

class Site(BaseModel):
    geometry:dict
class LayerQuery(Site):
    layer:str
    retry:bool=False
class ParcelPoint(BaseModel):
    lon:float=Field(ge=124,le=132,allow_inf_nan=False)
    lat:float=Field(ge=33,le=39.5,allow_inf_nan=False)

class Address(BaseModel):
    address:str=Field(min_length=5,max_length=200)
def area(g):
    if g.is_empty:return 0.0
    if g.geom_type=='Polygon':return round(abs(GEOD.geometry_area_perimeter(orient(g,1))[0]),2)
    return round(sum(area(v) for v in getattr(g,'geoms',[])),2)
def validate(value):
    try:
        if len(json.dumps(value))>1500000:raise ValueError()
        g=shape(value);a,b,c,d=g.bounds
        if g.geom_type not in ('Polygon','MultiPolygon') or g.is_empty or not g.is_valid:raise ValueError()
        if not all(math.isfinite(v) for v in g.bounds) or not (124<=a<c<=132 and 33<=b<d<=39.5):raise ValueError()
        if area(box(*g.bounds))>10000000:raise HTTPException(422,'조회 사각범위는 10㎢ 이하로 설정하세요. 대규모 사업지 분할조회는 아직 지원하지 않습니다.')
        return g
    except HTTPException:raise
    except Exception:raise HTTPException(422,'대한민국 WGS84 좌표의 유효한 Polygon/MultiPolygon이 필요합니다.')
def register(app,service):
    router=APIRouter(prefix='/api/development');snapshots={};lock=threading.Lock();diagnostics={}
    point_channel=VWorldChannel(1);display_channel=VWorldChannel(2);facts_channel=VWorldChannel(2,pause_on_transport_error=False)
    def jurisdiction(g):
        local=offline_region(g)
        if local:return local
        if not service._vworld_key():return 'UNKNOWN'
        try:
            r,_=service._vworld_get('https://api.vworld.kr/req/wfs',params={'key':service._vworld_key(),'domain':service._vworld_domain(),'service':'WFS','request':'GetFeature','version':'1.0.0','typename':'lt_c_adsido_info','srsname':'EPSG:4326','bbox':','.join(map(str,g.bounds)),'output':'application/json','maxfeatures':50},timeout=(4,20))
            r.raise_for_status();seoul=[];other=[]
            for f in r.json().get('features',[]):
                p={str(k).lower():str(v) for k,v in (f.get('properties') or {}).items()};v=shape(f['geometry'])
                if not v.is_valid:continue
                (seoul if p.get('ctp_kor_nm')=='서울특별시' or p.get('ctprvn_nm')=='서울특별시' or p.get('ctprvn_cd')=='11' else other).append(v)
            if seoul and unary_union(seoul).covers(g):return 'SEOUL'
            if other and unary_union(other+seoul).covers(g):return 'OUTSIDE_OR_MIXED'
        except Exception:pass
        return 'UNKNOWN'
    @router.get('/ui.js')
    def ui():return Response(Path(__file__).with_name('development-ui.js').read_text(),media_type='text/javascript',headers={'Cache-Control':'no-store'})
    @router.post('/snapshots')
    def create(data:Site):
        g=validate(data.geometry);p={'geometry':data.geometry,'area_m2':area(g),'region':jurisdiction(g),'region_source':'SEOUL_REFERENCE_20261028' if offline_region(g) else 'VWORLD_OR_UNKNOWN','created_at':time.time(),'expires_in':7200}
        with lock:
            for k in list(snapshots):
                if time.time()-snapshots[k]['created_at']>7200:del snapshots[k]
            if len(snapshots)>=100:raise HTTPException(503,'개발용 대상지 보관 한도입니다. 잠시 후 다시 시도하세요.')
            token=secrets.token_urlsafe(32);snapshots[token]=json.loads(json.dumps(p))
        return {'id':token,**p}
    @router.get('/snapshots/{token}')
    def get(token:str):
        with lock:
            p=snapshots.get(token)
            if not p or time.time()-p['created_at']>7200:raise HTTPException(404,'대상지가 만료되었습니다. 초기 화면에서 다시 확정하세요.')
            return json.loads(json.dumps(p))
    def failure(exc):
        # Categorize locally. Never return exception text or upstream URLs/keys.
        if isinstance(exc,ChannelFailure):return exc.code
        t=str(exc).lower()
        if not service._vworld_key():return 'SERVICE_NOT_READY'
        if 'circuit' in t or 'cooldown' in t:return 'TEMPORARILY_PAUSED'
        if '429' in t or '호출제한' in t:return 'RATE_LIMIT'
        if any(v in t for v in ('401','403','인증','domain','invalidkey','apikey')):return 'PROVIDER_REJECTED'
        if any(v in t for v in ('timeout','timed out','transport','connection','연결','외부연결')):return 'PROVIDER_UNREACHABLE'
        if 'json' in t or '파싱' in t:return 'PROVIDER_FORMAT'
        return 'REQUEST_FAILED'
    @router.post('/layer')
    def layer(data:LayerQuery):
        g=validate(data.geometry)
        if data.layer not in LAYERS:raise HTTPException(422,'지원하지 않는 레이어입니다.')
        base={'source':'VWorld','layer':data.layer,'name':LAYERS[data.layer],'queried_at':time.time()}
        try:
            if not service._vworld_key():raise RuntimeError('service not configured')
            # Nationwide facts have their own connection state, separate from map tiles.
            a,b,c,e=g.bounds;fs=[];seen=set();started=time.monotonic();route='direct'
            for page in range(1,11):
                if time.monotonic()-started>22:raise ChannelFailure('PROVIDER_UNREACHABLE')
                response,route=facts_channel.request('https://api.vworld.kr/req/data',{'key':service._vworld_key(),'domain':service._vworld_domain(),'service':'data','version':'2.0','request':'getfeature','format':'json','size':1000,'page':page,'geometry':'true','attribute':'true','crs':'EPSG:4326','data':data.layer,'geomfilter':f'BOX({a},{b},{c},{e})'},'json')
                try:payload=response.json().get('response') or {}
                finally:response.close()
                if payload.get('status')=='NOT_FOUND':break
                if payload.get('status')!='OK':raise ChannelFailure('PROVIDER_REJECTED')
                items=((payload.get('result') or {}).get('featureCollection') or {}).get('features')
                if not isinstance(items,list):raise ChannelFailure('PROVIDER_FORMAT')
                for feature in items:
                    if not feature.get('geometry'):raise ChannelFailure('PROVIDER_FORMAT')
                    try:
                        geom=shape(feature['geometry'])
                        if not geom.is_valid:raise ValueError()
                        intersects=geom.intersects(g)
                    except Exception:raise ChannelFailure('PROVIDER_FORMAT')
                    if not intersects:continue
                    props=feature.get('properties') or {}
                    key=str(feature.get('id') or props.get('pnu') or props.get('unq_mnno') or hashlib.sha256(json.dumps(feature['geometry'],sort_keys=True).encode()).hexdigest())
                    if key not in seen:seen.add(key);fs.append(feature)
                if len(items)<1000:break
            else:raise ChannelFailure('PROVIDER_FORMAT')
            intersections=[shape(f['geometry']).intersection(g) for f in fs]
            result={**base,'status':'COMPLETE','route':'SERVER','features':fs,'overlap_area_m2':area(unary_union(intersections)) if intersections else 0}
            diagnostic={'status':'COMPLETE','queried_at':base['queried_at'],'route':route,'count':len(fs)}
        except Exception as exc:
            code=failure(exc)
            diagnostic={'status':'UNKNOWN','queried_at':base['queried_at'],'error_code':code,'exception_type':type(exc).__name__}
            result={**base,'status':'UNKNOWN','features':[],'error_code':code,'message':'자료 연결 실패. 사업 적합성은 판정하지 않았습니다.'}
            state=facts_channel.snapshot()
            if code=='TEMPORARILY_PAUSED' and state.get('last_error_code')=='RATE_LIMIT':
                result['error_code']='RATE_LIMIT';diagnostic['error_code']='RATE_LIMIT'
            if result['error_code'] in ('TEMPORARILY_PAUSED','RATE_LIMIT'):
                result['retry_after_seconds']=max(1,state['retry_after_seconds'])
        with lock:diagnostics[data.layer]=diagnostic
        return result
    auth=getattr(service,'_admin_auth_or_session',None)
    if auth:
        @router.get('/admin/diagnostics',dependencies=[Depends(auth)])
        def diagnostic_report():
            with lock:entries=json.loads(json.dumps(diagnostics))
            return {'server_data_connection_configured':bool(service._vworld_key()),'configured_domain':urlsplit(service._vworld_domain()).hostname,'layers':entries,'channels':{'parcel_input':point_channel.snapshot(),'background_display':display_channel.snapshot(),'national_facts':facts_channel.snapshot()},'note':'키·토큰·원문 오류·요청 URL은 반환하지 않습니다.'}
    @router.post('/parcel-at-point')
    def parcel_at_point(data:ParcelPoint):
        # Point picking is a dedicated input operation, not a business analysis.
        try:
            if not service._vworld_key():raise RuntimeError('service not configured')
            project=Transformer.from_crs(4326,5179,always_xy=True).transform
            inverse=Transformer.from_crs(5179,4326,always_xy=True).transform
            point=shape({'type':'Point','coordinates':[data.lon,data.lat]})
            probe=transform(inverse,transform(project,point).buffer(8))
            from shapely.geometry import mapping
            a,b,c,e=probe.bounds
            response,route=point_channel.request('https://api.vworld.kr/req/data',{'key':service._vworld_key(),'domain':service._vworld_domain(),'service':'data','version':'2.0','request':'getfeature','format':'json','size':100,'page':1,'geometry':'true','attribute':'true','crs':'EPSG:4326','data':'LP_PA_CBND_BUBUN','geomfilter':f'BOX({a},{b},{c},{e})'},'json')
            try:payload=response.json().get('response') or {}
            finally:response.close()
            if payload.get('status')=='NOT_FOUND':features=[]
            elif payload.get('status')=='OK':
                features=((payload.get('result') or {}).get('featureCollection') or {}).get('features')
                if not isinstance(features,list) or len(features)>=100:raise ChannelFailure('PROVIDER_FORMAT')
            else:raise ChannelFailure('PROVIDER_REJECTED')
            hits={}
            for f in features:
                if not f.get('geometry'):continue
                try:
                    polygon=shape(f['geometry'])
                    if not polygon.is_valid or not polygon.covers(point):continue
                except Exception:continue
                props=dict(f.get('properties') or {})
                low={str(k).lower():v for k,v in props.items()}
                candidates=[low.get('pnu'),f.get('id')]
                pnu=next((str(v) for v in candidates if re.fullmatch(r'\d{19}',str(v or ''))),None)
                if not pnu:continue
                props['pnu']=pnu
                if low.get('jibun') is not None:props['jibun']=low['jibun']
                props['geometry_area_m2']=area(polygon)
                hits[pnu]={'type':'Feature','id':pnu,'geometry':f['geometry'],'properties':props}
            with lock:diagnostics['parcel_click']={'status':'COMPLETE','count':len(hits),'route':route,'queried_at':time.time()}
            if len(hits)>1:return {'status':'AMBIGUOUS','feature':None,'message':'클릭점이 필지 경계에 걸렸습니다. 필지 안쪽을 클릭하세요.'}
            if not hits:return {'status':'NOT_FOUND','feature':None,'message':'클릭점이 포함된 지적 필지를 확인하지 못했습니다. 필지 안쪽을 다시 클릭하세요.'}
            feature=next(iter(hits.values()))
            return {'status':'RESOLVED','feature':feature,'pnu':feature['properties']['pnu']}
        except Exception as exc:
            code=failure(exc)
            with lock:diagnostics['parcel_click']={'status':'UNKNOWN','error_code':code,'exception_type':type(exc).__name__,'queried_at':time.time()}
            return {'status':'UNKNOWN','feature':None,'error_code':code,'message':'클릭 지적자료를 확보하지 못했습니다.'}
    @router.post('/address')
    def address(data:Address):
        if not re.match(r'^(서울|부산|대구|인천|광주|대전|울산|세종|경기|강원|충청|충북|충남|전라|전북|전남|경상|경북|경남|제주)',data.address):raise HTTPException(422,'시·도부터 정식 지번주소를 입력하세요.')
        try:
            r,_=service._vworld_get(service.VWORLD_SEARCH_URL,params={'key':service._vworld_key(),'domain':service._vworld_domain(),'service':'search','version':'2.0','request':'search','format':'json','size':10,'page':1,'query':data.address,'type':'ADDRESS','category':'parcel','crs':'EPSG:4326'},timeout=(4,15))
            r.raise_for_status();p=r.json().get('response',{})
            if p.get('status') not in ('OK','NOT_FOUND'):raise ValueError()
            norm=lambda v:re.sub(r'\s+','',str(v or ''))
            hits=[it for it in (p.get('result') or {}).get('items',[]) if norm((it.get('address') or {}).get('parcel'))==norm(data.address)]
            if len(hits)!=1:return {'status':'not_found','feature':None,'message':'정확히 일치하는 주소가 없습니다. 정식 시·도명과 지번을 확인하세요.'}
            pnu=service._vworld_pnu_from_search_item(hits[0])
            if not pnu:raise ValueError()
            v=service._vworld_parcel_by_pnu(pnu,force_retry=True)
            return {'status':v.get('status'),'feature':v.get('feature'),'pnu':pnu,'address':data.address}
        except Exception:raise HTTPException(502,'주소자료 조회 실패. API 설정 또는 주소를 확인하세요.')
    @router.get('/wms/{kind}')
    def wms(kind:str,request:Request):
        groups={'cadastral':'lp_pa_cbnd_bubun','zoning':','.join(f'lt_c_uq11{i}' for i in range(1,5)),'facility':','.join(f'lt_c_upisuq15{i}' for i in range(1,10))}
        if kind not in groups:raise HTTPException(404)
        q={k.lower():v for k,v in request.query_params.items()}
        try:
            bounds=[float(v) for v in q['bbox'].split(',')];a,b,c,d=bounds;w=int(q.get('width',256));h=int(q.get('height',256))
            if not all(math.isfinite(v) for v in bounds) or not (13000000<=a<c<=15000000 and 3000000<=b<d<=5000000 and 1<=w<=1024 and 1<=h<=1024):raise ValueError()
        except Exception:raise HTTPException(422,'지도 요청범위를 확인하세요.')
        try:
            r,_=display_channel.request('https://api.vworld.kr/req/wms',{'key':service._vworld_key(),'domain':service._vworld_domain(),'service':'WMS','request':'GetMap','version':'1.1.1','srs':'EPSG:3857','bbox':','.join(map(str,bounds)),'width':w,'height':h,'layers':groups[kind],'styles':groups[kind],'format':'image/png','transparent':'TRUE'},'png')
            if r.status_code!=200 or not r.content.startswith(b'\x89PNG\r\n\x1a\n'):raise ValueError()
            image=r.content;r.close()
            return Response(image,media_type='image/png',headers={'Cache-Control':'private,max-age=120'})
        except Exception:raise HTTPException(503,'지도자료 미확보')
    app.include_router(router)
